service.method:

SELECT count(*) CNT
  FROM SFORM
 WHERE 1=1
   AND HOUSE_CODE = ${session.HOUSE_CODE}
   AND FORM_ID    = ${FORM_ID}


UPDATE #DB_OWNER#SFORM 
   SET FORM_JSON        = ${FORM_JSON}
      ,CHANGE_USER_ID   = ${session.ID}        
  	  ,CHANGE_DATE      = ${current.date}      
  	  ,CHANGE_TIME      = ${current.time}      
 WHERE HOUSE_CODE 		= ${session.HOUSE_CODE}
   AND FORM_ID          = ${FORM_ID}


DELETE 
  FROM #DB_OWNER#SFORM 
 WHERE HOUSE_CODE 		= ${session.HOUSE_CODE}
   AND FORM_ID          = ${FORM_ID}


	SELECT COUNT(*) CNT
	  FROM #DB_OWNER#SLANG 
	 WHERE SCREEN_ID  = ${FORM_ID}
  	   AND LANGUAGE   = ${session.LANGUAGE}
  	   AND CODE		  = ${CODE}
  	   AND HOUSE_CODE = ${session.HOUSE_CODE}


	UPDATE #DB_OWNER#SLANG 
       SET CONTENTS    = ${CONTENTS}
         , CHANGE_DATE = ${current.DATE}
		 , CHANGE_TIME = ${current.TIME}
     WHERE SCREEN_ID  = ${FORM_ID}
       AND CODE       = ${CODE}
       AND HOUSE_CODE = ${session.HOUSE_CODE}
       AND LANGUAGE   = ${session.LANGUAGE}
